import { describe, it, expect } from 'vitest';
import { parseGCodeContent } from '../gcodeService';

describe('gcodeService - Parser Multi-Slicer (.gcode)', () => {
  it('extrae tiempo, gramos, colores AMS y nombre de archivo en formato Bambu Studio / OrcaSlicer', () => {
    const sample = `
; generated by BambuStudio 1.9.1
; model printing time: 3h 42m 18s; total estimated printing time: 3h 55m 10s
; total filament used [g] : 100.20, 48.45
; total filament flush weight [g] : 18.5
; filament_type = PLA;PLA
G28
`;
    const res = parseGCodeContent(sample, 'Goku_Busto_AMS.gcode');
    expect(res.slicerDetectado).toBe('Bambu Studio / OrcaSlicer');
    expect(res.tiempoMinutos).toBe(235); // 3*60 + 55
    expect(res.pesoGramos).toBeCloseTo(148.65, 1);
    expect(res.pesoPurgaGramos).toBeCloseTo(18.5, 1);
    expect(res.esMulticolorAMS).toBe(true);
    expect(res.cantidadColores).toBe(2);
    expect(res.nombreSugerido).toBe('Goku Busto AMS');
  });

  it('extrae tiempo y gramos en formato PrusaSlicer', () => {
    const sample = `
; generated by PrusaSlicer 2.7.2 on 2026-03-01
; estimated printing time (normal mode) = 2h 15m 40s
; filament used [g] = 84.32
M104 S210
`;
    const res = parseGCodeContent(sample, 'Llavero.gcode');
    expect(res.slicerDetectado).toBe('PrusaSlicer');
    expect(res.tiempoMinutos).toBe(136);
    expect(res.pesoGramos).toBeCloseTo(84.32, 1);
  });

  it('extrae tiempo en segundos y peso en formato Cura', () => {
    const sample = `
;FLAVOR:Marlin
;TIME:7260
;Filament weight: 52.4
G28
`;
    const res = parseGCodeContent(sample, 'Soporte_Cura.gcode');
    expect(res.slicerDetectado).toBe('Cura');
    expect(res.tiempoMinutos).toBe(121);
    expect(res.pesoGramos).toBeCloseTo(52.4, 1);
  });
});
